          "jsCode": "const raw = $input.first().json.output || $input.first().json.text || '';\n\n// Extract JSON array from response (handle markdown code fences)\nlet jsonStr = raw;\nconst fenceMatch = raw.match(/```(?:json)?\\s*([\\s\\S]*?)```/);\nif (fenceMatch) {\n  jsonStr = fenceMatch[1].trim();\n}\n\n// Try to find array brackets if not already clean\nconst arrayMatch = jsonStr.match(/(\\[[\\s\\S]*\\])/);\nif (arrayMatch) {\n  jsonStr = arrayMatch[1];\n}\n\nlet strategies;\ntry {\n  strategies = JSON.parse(jsonStr);\n} catch (e) {\n  return [{\n    json: {\n      error: 'Failed to parse Ollama output as JSON',\n      raw_output: raw.substring(0, 500),\n      parse_error: e.message\n    }\n  }];\n}\n\nif (!Array.isArray(strategies)) {\n  strategies = [strategies];\n}\n\nconst enriched = strategies.map(s => ({\n  json: {\n    strategy_name: s.strategy_name || 'unnamed',\n    one_sentence: s.one_sentence || '',\n    python_code: s.python_code || '',\n    params: s.params || {},\n    symbol: 'ES',\n    timeframe: '15min',\n    start_date: '2024-01-01',\n    end_date: '2024-12-31',\n    source: 'ollama'\n  }\n}));\n\nreturn enriched;"
